UPDATE ad_budget_account SET held_amount=held_amount-#{amount},charged_amount=charged_amount+#{charge},version=version+1,updated_at=#{now}
WHERE traffic_class='SANDBOX' AND advertiser_id=#{account.advertiserId} AND budget_date=#{account.budgetDate} AND currency='CNY'
    AND version=#{account.version} AND held_amount >= #{amount}
